"use client"

import { useEffect, useState } from "react"
import Link from "next/link"
import { TrendingUp, Wallet, Receipt, Users, Truck, ArrowRight } from "lucide-react"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { useI18n } from "@/lib/i18n"
import { useAuthStore } from "@/lib/auth-store"
import { api, monthStartStr, todayStr } from "@/lib/acct-client"
import { AnimatedNumber } from "@/components/motion/animated-number"

// Month-to-date finance snapshot on the dashboard (admin + contador only).
export function FinanceSummary() {
  const { t } = useI18n()
  const role = useAuthStore((s) => s.user?.role)
  const staff = role === "admin" || role === "contador"
  const [d, setD] = useState<any>(null)
  useEffect(() => { if (staff) api("accounting/summary", { params: { from: monthStartStr(), to: todayStr() } }).then(setD).catch(() => setD(null)) }, [staff])
  if (!staff || !d) return null
  const items = [
    // Green/red only where money goes up or down (net results); balances stay neutral.
    { k: t("acct.dash.netMonth"), v: d.pnl.net, icon: TrendingUp, tone: d.pnl.net > 0 ? "text-positive" : d.pnl.net < 0 ? "text-negative" : "" },
    { k: t("acct.cash.net"), v: d.cash.net, icon: Wallet, tone: d.cash.net > 0 ? "text-positive" : d.cash.net < 0 ? "text-negative" : "" },
    { k: t("acct.acc.receivables"), v: d.receivables.total, icon: Receipt, tone: "" },
    { k: t("acct.acc.payables"), v: d.payables.total, icon: Truck, tone: "" },
    { k: t("acct.acc.payrollOwed"), v: d.payroll.owed, icon: Users, tone: "" },
  ]
  return (
    <Card>
      <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
        <CardTitle className="text-base">{t("acct.dash.title")}</CardTitle>
        <Button asChild variant="ghost" size="sm"><Link href="/accounting">{t("acct.dash.open")}<ArrowRight className="ml-1 h-4 w-4" /></Link></Button>
      </CardHeader>
      <CardContent>
        <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-5">
          {items.map((i) => { const Icon = i.icon; return (
            <div key={i.k} className="rounded-md border p-3">
              <div className="flex items-center gap-1 text-xs text-muted-foreground"><Icon className="h-3.5 w-3.5" />{i.k}</div>
              <AnimatedNumber value={Number(i.v) || 0} format="usd" className={`mt-1 block text-lg font-bold tabular-nums ${i.tone}`} />
            </div>
          ) })}
        </div>
      </CardContent>
    </Card>
  )
}
