"use client"

import { useEffect, useRef, useState } from "react"
import { formatUSD } from "@/lib/money"

type Format = "usd" | "int"
const fmt = (v: number, f: Format) => (f === "usd" ? formatUSD(v) : Math.round(v).toLocaleString("en-US"))

function prefersReducedMotion() {
  return typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches
}

/**
 * Count-up for dashboard KPI cards only. Runs once per page load (~700 ms,
 * ease-out) the first time a non-zero value arrives, and the last frame is
 * always the exact value rendered with the shared formatter. Later changes
 * jump straight to the new value. Screen readers get the final value only.
 */
export function AnimatedNumber({ value, format = "int", duration = 700, className }: { value: number; format?: Format; duration?: number; className?: string }) {
  const safe = Number.isFinite(value) ? value : 0
  const [shown, setShown] = useState(safe)
  const done = useRef(false)

  useEffect(() => {
    if (done.current || safe === 0 || prefersReducedMotion()) {
      if (safe !== 0) done.current = true
      setShown(safe)
      return
    }
    done.current = true
    let raf = 0
    const start = performance.now()
    const tick = (now: number) => {
      const t = Math.min(1, (now - start) / duration)
      const eased = 1 - Math.pow(1 - t, 3)
      if (t < 1) {
        setShown(safe * eased)
        raf = requestAnimationFrame(tick)
      } else {
        setShown(safe) // exact final value
      }
    }
    setShown(0)
    raf = requestAnimationFrame(tick)
    return () => {
      cancelAnimationFrame(raf)
      setShown(safe)
    }
  }, [safe, duration])

  return (
    <span className={className}>
      <span aria-hidden="true" className="tabular-nums">{fmt(shown, format)}</span>
      <span className="sr-only">{fmt(safe, format)}</span>
    </span>
  )
}
