"use client"

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { FileText } from "lucide-react"
import { useDataStore } from "@/lib/data-store"
import { useI18n } from "@/lib/i18n"
import { FadeItem } from "@/components/motion/fade-row"
import { EmptyState } from "@/components/motion/empty-state"

export function RecentActivity() {
  const { t } = useI18n()
  const activities = useDataStore((s) => s.activities || [])

  const safe = (v: any) => {
    try {
      if (v == null) return ''
      if (typeof v === 'string') return v
      if (typeof v === 'number') return String(v)
      if (v && typeof v.toString === 'function') {
        const s = v.toString()
        if (s && s !== '[object Object]') return s
      }
      return JSON.stringify(v)
    } catch (e) { return String(v) }
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle>{t('dashboard.recentActivity.title')}</CardTitle>
      </CardHeader>
      <CardContent>
        <div className="space-y-4">
          {activities.length === 0 && <EmptyState text={t('dashboard.empty.activity')} />}
          {activities.map((activity, index) => {
            const Icon = FileText
            return (
              <FadeItem key={activity.id || index} index={index} className="flex items-start gap-4">
                <div className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-muted`}> 
                  <Icon className="h-5 w-5" />
                </div>
                <div className="flex-1 space-y-1">
                  <p className="text-sm font-medium leading-none">{safe(activity.title)}</p>
                  <p className="text-sm text-muted-foreground">{safe(activity.description)}</p>
                  <p className="text-xs text-muted-foreground">{safe(activity.time)}</p>
                </div>
              </FadeItem>
            )
          })}
        </div>
      </CardContent>
    </Card>
  )
}
