"use client"

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Calendar, Clock, User } from "lucide-react"
import { Badge } from "@/components/ui/badge"
import { useDataStore } from "@/lib/data-store"
import { useI18n } from "@/lib/i18n"
import { FadeItem } from "@/components/motion/fade-row"
import { EmptyState } from "@/components/motion/empty-state"

export function UpcomingTasks() {
  const { t } = useI18n()
  const tasks = useDataStore((s) => s.tasks || [])

  const safe = (v: any) => {
    try {
      if (v == null) return ''
      if (typeof v === 'string') return v
      if (typeof v === 'number') return String(v)
      if (v && typeof v.toString === 'function') {
        const s = v.toString()
        if (s && s !== '[object Object]') return s
      }
      return JSON.stringify(v)
    } catch (e) { return String(v) }
  }
  return (
    <Card>
      <CardHeader>
        <CardTitle>{t('dashboard.upcoming.title')}</CardTitle>
      </CardHeader>
      <CardContent>
        <div className="space-y-4">
          {tasks.length === 0 && <EmptyState text={t('dashboard.empty.tasks')} />}
          {tasks.map((task, index) => (
            <FadeItem key={task.id || index} index={index} className="flex items-start justify-between gap-4 rounded-lg border p-4">
              <div className="flex-1 space-y-2">
                <div className="flex items-center gap-2">
                  <h4 className="font-medium">{task.title}</h4>
                  <Badge variant={task.priority === "high" ? "default" : "secondary"}>{t(`tasks.priority.${task.priority}`) || task.priority}</Badge>
                </div>
                <div className="flex flex-col gap-1 text-sm text-muted-foreground">
                  <div className="flex items-center gap-2">
                    <Calendar className="h-3 w-3" />
                    <span>{safe(task.project || task.client)}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <Clock className="h-3 w-3" />
                    <span>{safe(task.dueDate || task.date)}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <User className="h-3 w-3" />
                    <span>{safe(task.assignee)}</span>
                  </div>
                </div>
              </div>
            </FadeItem>
          ))}
        </div>
      </CardContent>
    </Card>
  )
}
