"use client"

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Line, LineChart, ResponsiveContainer, Tooltip, XAxis, YAxis, CartesianGrid } from "recharts"
import { useDataStore } from "@/lib/data-store"
import { useI18n } from "@/lib/i18n"
import { formatUSD } from "@/lib/money"
import { useChartAnimation, chartTooltipStyle } from "@/components/motion/chart-anim"
import { EmptyState } from "@/components/motion/empty-state"

function monthNameByLocale(date: Date | null, locale: string, unknown: string) {
  if (!date || isNaN(date.getTime())) return unknown
  try {
    return new Intl.DateTimeFormat(locale, { month: 'short' }).format(date)
  } catch (e) {
    return date.toLocaleString(undefined, { month: 'short' })
  }
}

export function RevenueChart() {
  const { t, locale } = useI18n()
  const projects = useDataStore((s) => s.projects || [])
  const anim = useChartAnimation()

  // Aggregate by project.startDate month (localized month labels)
  const agg: Record<string, number> = {}
  projects.forEach((p) => {
    const sd = p && (p.startDate || p.start_date) ? (typeof p.startDate === 'string' ? p.startDate : (p.start_date && typeof p.start_date === 'string' ? p.start_date : String(p.startDate || p.start_date))) : ''
    const date = sd ? new Date(sd) : null
    const monthLabel = monthNameByLocale(date, locale || 'en-US', t('dashboard.unknownMonth'))
    agg[monthLabel] = (agg[monthLabel] || 0) + (Number(p.value) || 0)
  })

  const data = Object.keys(agg).map((m) => ({ month: m, revenue: agg[m] }))

  return (
    <Card>
      <CardHeader>
        <CardTitle>{t('dashboard.revenue.title')}</CardTitle>
      </CardHeader>
      <CardContent>
        {data.every((d) => !d.revenue) ? (
          <EmptyState text={t('dashboard.empty.revenue')} />
        ) : (
        <ResponsiveContainer width="100%" height={300}>
          <LineChart data={data}>
            <CartesianGrid strokeDasharray="3 3" stroke="var(--border)" />
            <XAxis dataKey="month" tick={{ fill: "var(--muted-foreground)", fontSize: 12 }} stroke="var(--border)" />
            <YAxis tick={{ fill: "var(--muted-foreground)", fontSize: 12 }} stroke="var(--border)" tickFormatter={(v) => formatUSD(Number(v)).replace(/\.00$/, "")} width={80} />
            <Tooltip contentStyle={chartTooltipStyle} formatter={(v: any) => formatUSD(Number(v))} />
            <Line type="monotone" dataKey="revenue" name={t('dashboard.revenue.series')} stroke="var(--chart-1)" strokeWidth={2} dot={{ r: 3, fill: "var(--chart-1)" }} {...anim} />
          </LineChart>
        </ResponsiveContainer>
        )}
      </CardContent>
    </Card>
  )
}
