"use client"

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { useDataStore } from "@/lib/data-store"
import { useI18n } from "@/lib/i18n"
import * as m from "motion/react-m"
import { EmptyState } from "@/components/motion/empty-state"

export function PipelineOverview() {
  const { t } = useI18n()
  const deals = useDataStore((s) => s.deals || [])

  const counts = deals.reduce<Record<string, number>>((acc, d) => {
    const k = d && d.stage ? String(d.stage) : 'unknown'
    acc[k] = (acc[k] || 0) + 1
    return acc
  }, {})

  const stages = Object.keys(counts).map((k) => ({ name: k, count: counts[k] }))
  const total = stages.reduce((sum, stage) => sum + stage.count, 0) || 1

  return (
    <Card>
      <CardHeader>
        <CardTitle>{t('dashboard.pipeline.title')}</CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {stages.length === 0 && <EmptyState text={t("dashboard.empty.pipeline")} />}
        {stages.map((stage, i) => {
          const percentage = (stage.count / total) * 100
          return (
            <div key={stage.name} className="space-y-2">
              <div className="flex items-center justify-between text-sm">
                <span className="font-medium">{t(`pipeline.stage.${stage.name}`) || stage.name}</span>
                <span className="text-muted-foreground">{stage.count} {t('dashboard.deals')}</span>
              </div>
              <div className="h-2 w-full rounded-full bg-muted">
                {/* Bars "draw" in 500 ms via scaleX (transform only; instant under reduced motion). */}
                <m.div
                  className="h-full origin-left rounded-full bg-foreground/80"
                  style={{ width: `${percentage}%` }}
                  initial={{ scaleX: 0 }}
                  animate={{ scaleX: 1 }}
                  transition={{ duration: 0.5, ease: "easeOut", delay: i * 0.03 }}
                />
              </div>
            </div>
          )
        })}
      </CardContent>
    </Card>
  )
}
